import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/dungeon/commands.md","filePath":"modules/dungeon/commands.md","lastUpdated":0}`),a={name:`modules/dungeon/commands.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to “命令与权限”">​</a></h1><p>EmakiDungeon 的主命令是 <code>/edungeon</code>, 短别名 <code>/ed</code>. 玩家侧命令默认都开放 (<code>emakidungeon.play</code> 默认为 <code>true</code>), 管理与编辑器命令则需要对应权限</p><h2 id="玩家命令" tabindex="-1">玩家命令 <a class="header-anchor" href="#玩家命令" aria-label="Permalink to “玩家命令”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>所需权限</th></tr></thead><tbody><tr><td><code>/edungeon help</code></td><td>查看命令帮助 (无参数时等同于 help)</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edungeon list</code></td><td>查看当前可用的副本列表</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edungeon enter &lt;副本ID&gt;</code></td><td>发起挑战并进入副本; 组队状态下<strong>仅队长可发起</strong></td><td><code>emakidungeon.play</code> + <code>emakidungeon.dungeon.&lt;副本ID&gt;</code></td></tr><tr><td><code>/edungeon leave</code></td><td>退出当前副本; 会先二次确认, 聊天输入 <code>确认</code> 退出, 输入 <code>取消</code> 放弃</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edungeon cancel</code></td><td>取消进行中的进入等待或挑战流程 (准备窗口内任一队员可取消)</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edungeon ready</code></td><td>准备确认窗口内确认就绪 (也可以点击弹出的确认按钮)</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edungeon rewards</code></td><td>打开个人奖励箱领取通关奖励</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edungeon stats [玩家] [副本ID]</code></td><td>查询进入次数 (日/周/月与冷却) 和最佳成绩</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edungeon rank &lt;副本ID&gt;</code></td><td>查看该副本排行榜前 10 名 (分数, 用时, 难度, 队伍)</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edungeon globalchat &lt;on|off&gt;</code></td><td>切换全局消息收听; <code>on</code> 后实例内外消息互通, <code>off</code> 时副本内消息只在实例内闭环</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edungeon editor &lt;副本ID&gt;</code></td><td>打开地图编辑器, 进入该副本的独立编辑世界</td><td><code>emakidungeon.editor</code></td></tr><tr><td><code>/edungeon recruit &lt;open|close|list|join&gt;</code></td><td>组队招募板: <code>open &lt;副本ID&gt; [难度]</code> 发布招募 (仅队长), <code>close</code> 关闭招募, <code>list</code> 查看进行中的招募, <code>join &lt;编号&gt;</code> 加入招募</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edungeon match &lt;join|leave&gt;</code></td><td>本服自动匹配: <code>join &lt;副本ID&gt; [难度]</code> 加入匹配队列, <code>leave</code> 离开匹配队列</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edungeon spectate &lt;next|prev&gt;</code></td><td>观战模式下切换观战目标 (下一个 / 上一个); 不在观战模式时提示</td><td><code>emakidungeon.play</code></td></tr></tbody></table><p>招募板与自动匹配由全局 <code>matchmaking</code> 段控制 (关闭时两者都提示已关闭), 招募贴按 <code>matchmaking.recruit-ttl-seconds</code> 过期; 匹配成功后由队长用 <code>/edungeon enter &lt;副本ID&gt;</code> 发起挑战</p><h2 id="队伍子命令" tabindex="-1">队伍子命令 <a class="header-anchor" href="#队伍子命令" aria-label="Permalink to “队伍子命令”">​</a></h2><p>用 <code>/edungeon party &lt;子命令&gt;</code> 管理队伍:</p><table tabindex="0"><thead><tr><th>子命令</th><th>说明</th><th>限制</th></tr></thead><tbody><tr><td><code>create</code></td><td>创建一支新队伍 (自己当队长)</td><td>已在队伍中时不可再建</td></tr><tr><td><code>invite &lt;玩家&gt;</code></td><td>自己有队伍: 邀请对方入队 (仅队长); 自己没队伍: 向对方发起加入, 按邀请模式处理</td><td>有队伍时仅队长可执行</td></tr><tr><td><code>accept</code></td><td>邀请的接收方用来接受邀请; 申请的接收方 (队长) 用来批准申请</td><td>按收到的是邀请还是申请而定</td></tr><tr><td><code>deny</code></td><td>拒绝收到的邀请 (被邀请者) 或拒绝入队申请 (队长)</td><td>按收到的是邀请还是申请而定</td></tr><tr><td><code>kick &lt;玩家&gt;</code></td><td>踢出队员</td><td>仅队长</td></tr><tr><td><code>leave</code></td><td>自己离队 (队长离队时移交给其他队员)</td><td>—</td></tr><tr><td><code>disband</code></td><td>解散整支队伍</td><td>仅队长</td></tr><tr><td><code>chat</code></td><td>切换队伍频道: 开启后你的消息只有队伍可见</td><td>—</td></tr></tbody></table><p>邀请模式由全局配置 <code>party.invite-mode</code> 决定, 它控制没队伍的玩家向别人发起加入时的结果: <code>public</code> 直接加入, <code>apply</code> 提交申请等队长批准, <code>invite</code> 只有被邀请的人才能加入 (其他值按 <code>invite</code> 处理); 队伍人数上限见 <code>party.max-size</code></p><h2 id="随机地牢命令" tabindex="-1">随机地牢命令 <a class="header-anchor" href="#随机地牢命令" aria-label="Permalink to “随机地牢命令”">​</a></h2><p><code>type: random</code> 的副本走随机生成玩法, 用 <code>/edungeon random &lt;子命令&gt;</code> 操作:</p><table tabindex="0"><thead><tr><th>子命令</th><th>说明</th><th>所需权限</th></tr></thead><tbody><tr><td><code>create &lt;副本ID&gt; [人数] [种子]</code></td><td>按随机生成配置为该副本创建一个随机地牢实例; 人数影响房量, 种子留空随机; <strong>仅 <code>type: random</code> 的副本可用</strong>, 其他类型直接拒绝</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>enter &lt;实例ID&gt;</code></td><td>进入已创建的随机地牢实例</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>leave</code></td><td>离开当前随机地牢实例</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>list</code></td><td>列出运行中的随机地牢实例 (实例 ID, 状态, 房间数, 种子)</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>records</code></td><td>列出实例记录 (记录 ID 可用于 <code>replay</code>)</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>stop &lt;实例ID&gt;</code></td><td>强制停止指定随机地牢实例</td><td><code>emakidungeon.admin</code></td></tr><tr><td><code>replay &lt;记录ID&gt;</code></td><td>按实例记录重新推演布局做回放校验</td><td><code>emakidungeon.admin</code></td></tr><tr><td><code>reload</code></td><td>重载 <code>random-dungeon.yml</code> 与全部副本的结构模板</td><td><code>emakidungeon.admin</code></td></tr></tbody></table><p>随机地牢的结构模板 (房间 / 走廊) 由编辑器的区域采集功能产出, 落库在 <code>plugins/EmakiDungeon/world/&lt;副本ID&gt;/structures/</code>; 采集流程见下面的编辑器会话命令, 生成参数见 <a href="./configuration.html">配置详解</a></p><h2 id="编辑器会话命令" tabindex="-1">编辑器会话命令 <a class="header-anchor" href="#编辑器会话命令" aria-label="Permalink to “编辑器会话命令”">​</a></h2><p>拥有 <code>emakidungeon.editor</code> 权限的玩家执行 <code>/edungeon editor &lt;副本ID&gt;</code> 后进入该副本的独立编辑世界与编辑会话, 可用子命令 (<code>/edungeon editor &lt;子命令&gt;</code>):</p><table tabindex="0"><thead><tr><th>子命令</th><th>说明</th></tr></thead><tbody><tr><td><code>menu</code></td><td>打开编辑主面板; <code>type: random</code> 的副本改为打开随机区域采集 GUI</td></tr><tr><td><code>pos1</code> / <code>pos2</code></td><td>记录区域的第一个 / 第二个角点 (站到目标区域的两个对角各记一次); <code>type: random</code> 的副本里用于框选要采集的结构区域</td></tr><tr><td><code>anchor add &lt;锚点ID&gt; &lt;朝向&gt; &lt;宽&gt; &lt;高&gt;</code></td><td>在准星落点 (12 格内) 登记一个门点位: 朝向取 <code>n</code> / <code>e</code> / <code>s</code> / <code>w</code>, 宽高为门洞尺寸 (1–16); 需先框选区域, 仅 <code>type: random</code> 副本可用</td></tr><tr><td><code>anchor remove &lt;锚点ID&gt;</code></td><td>移除指定门点位; 仅 <code>type: random</code> 副本可用</td></tr><tr><td><code>status</code></td><td>查看当前区域采集会话 (结构类型, 标签, 门点位数, 点位数, 楼层); 仅 <code>type: random</code> 副本可用</td></tr><tr><td><code>mark &lt;类型&gt; [id]</code></td><td>在视线 16 格内的方块上放一个标记, 暂存到会话, 保存后写入 <code>flow.yml</code></td></tr><tr><td><code>marks</code></td><td>列出本会话已暂存的标记</td></tr><tr><td><code>save</code></td><td>把暂存的标记与面板改动回写模板文件并保存地形 (等同面板里的&quot;保存并回写模板&quot;)</td></tr><tr><td><code>fill &lt;方块&gt;</code></td><td>用 <code>pos1</code> + <code>pos2</code> 圈出的区域批量填方块 (分帧写入, 有数量上限)</td></tr><tr><td><code>test</code></td><td>测试开局: 走正常进入流程, <strong>不计次数, 不上榜</strong>; 有未保存改动时会被拒绝</td></tr><tr><td><code>exit</code></td><td>退出会话; 有未保存改动时会先拒绝, 要求保存或放弃</td></tr></tbody></table><p><code>anchor</code> 与 <code>status</code> 在非随机类型的副本里会提示仅随机类型可用; <code>menu</code> / <code>pos1</code> / <code>pos2</code> 会按副本类型自动分流语义</p><p>标记按坐标记法分三种, 共 21 种模块类型 (与 <code>flow.yml</code> 的功能模块一一对应):</p><table tabindex="0"><thead><tr><th>类型</th><th>记法</th><th>用途</th></tr></thead><tbody><tr><td><code>entry</code></td><td>单点</td><td>入口落点 (全副本唯一, 重复放置会被拒绝)</td></tr><tr><td><code>room</code></td><td>区域</td><td>房间</td></tr><tr><td><code>checkpoint</code></td><td>区域</td><td>检查点</td></tr><tr><td><code>respawn</code></td><td>单点</td><td>重生点</td></tr><tr><td><code>exit</code></td><td>单点</td><td>出口</td></tr><tr><td><code>gate</code></td><td>区域</td><td>门禁封门区</td></tr><tr><td><code>spawn</code></td><td>单点</td><td>刷怪点</td></tr><tr><td><code>trigger</code></td><td>区域</td><td>触发区</td></tr><tr><td><code>block</code></td><td>单点</td><td>方块交互</td></tr><tr><td><code>chest</code></td><td>单点</td><td>奖励点</td></tr><tr><td><code>option</code></td><td>单点</td><td>选项节点</td></tr><tr><td><code>tip</code></td><td>单点</td><td>提示点</td></tr><tr><td><code>teleport</code></td><td>区域</td><td>传送区</td></tr><tr><td><code>boundary</code></td><td>区域</td><td>边界区</td></tr><tr><td><code>effect</code></td><td>区域</td><td>效果区</td></tr><tr><td><code>mechanism</code></td><td>区域</td><td>机关</td></tr><tr><td><code>room_timer</code></td><td>区域</td><td>房间计时</td></tr><tr><td><code>kill_target</code></td><td>无坐标</td><td>击杀目标</td></tr><tr><td><code>item</code></td><td>单点</td><td>物品交互</td></tr><tr><td><code>fx</code></td><td>单点</td><td>特效点</td></tr><tr><td><code>temp_item</code></td><td>无坐标</td><td>临时物品</td></tr></tbody></table><p>记法说明: 单点标记对准方块直接记; 区域标记需要 <code>pos1</code> + <code>pos2</code> 两个角点 (未记角点时首次 <code>mark</code> 会先把视线落点记为 <code>pos1</code>); 无坐标标记不落坐标, 只登记配置项. 每种类型可配的字段见 <a href="./flow.html">流程与触发器</a>. Boss 不是独立标记: 刷怪点波次里的生物条目用 <code>boss: true</code> 标记</p><p>普通副本的编辑主面板 (元数据, 刷怪点与波次, 门禁, 分支选项) 通过 GUI 操作; <strong>标记和面板改动都只是暂存, 点击&quot;保存并回写模板&quot; (或执行 <code>save</code>) 后才写进模板文件</strong>; 未保存就退出会丢弃全部改动</p><p><code>type: random</code> 的副本里, 空手右键打开<strong>区域采集 GUI</strong> (元数据与标签, 门点位, 功能模块点位, 选区, 创建区域等面板): 主面板的&quot;创建区域&quot;可选<strong>房间 / 走廊</strong>, 按当前 <code>pos1</code> / <code>pos2</code> 选区落库到 <code>world/&lt;副本ID&gt;/structures/</code>, ID 自动编号为 <code>room_N</code> / <code>corridor_N</code>; 落库后会话自动复位为新区域, 再次用 <code>pos1</code> / <code>pos2</code> 框选就是下一个结构</p><p>同一副本模板同时只允许一个编辑会话</p><h2 id="管理命令" tabindex="-1">管理命令 <a class="header-anchor" href="#管理命令" aria-label="Permalink to “管理命令”">​</a></h2><p>用 <code>/edungeon admin &lt;子命令&gt;</code> 执行管理操作, 需要 <code>emakidungeon.admin</code> 权限 (默认 OP):</p><table tabindex="0"><thead><tr><th>子命令</th><th>说明</th></tr></thead><tbody><tr><td><code>instances</code></td><td>列出全部运行中的实例 (实例 ID, 副本, 状态, 队伍, 写队列积压)</td></tr><tr><td><code>inspect &lt;实例ID&gt;</code></td><td>查看实例详情: 难度, 掉落, 类型, 测试, 队伍, 已运行时长与流程时间线</td></tr><tr><td><code>stop &lt;实例ID&gt;</code></td><td>强制结束指定实例</td></tr><tr><td><code>status</code></td><td>运行状态总览: 实例数, 存活虚拟线程, 副本模板数, 各池占用与写队列</td></tr><tr><td><code>reload</code></td><td>重载主配置与<strong>全部副本</strong>配置; 运行中的实例不受影响, 只对之后新建的实例生效</td></tr><tr><td><code>validate</code></td><td>校验全部副本模板, 报告缺失 <code>flow.yml</code> 或配置非法的副本</td></tr><tr><td><code>poolreset &lt;副本ID&gt;</code></td><td>强制重置该副本的池补位世界</td></tr><tr><td><code>clearslots</code></td><td>清理残留的池占位记录</td></tr></tbody></table><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p><code>admin</code> 子命令在玩家判定之前分发, <code>reload</code> 也没有&quot;只能由玩家执行&quot;的限制: 控制台直接执行 <code>/edungeon admin reload</code> 即可重载, 脚本与假人同理; 玩家执行要求 <code>emakidungeon.admin</code> 权限, 控制台默认拥有全部权限</p></div><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to “权限节点”">​</a></h2><table tabindex="0"><thead><tr><th>节点</th><th>默认</th><th>用途</th></tr></thead><tbody><tr><td><code>emakidungeon.play</code></td><td>所有玩家</td><td>进入, 组队, 查询, 全局收听等玩家侧命令</td></tr><tr><td><code>emakidungeon.dungeon.*</code></td><td>所有玩家</td><td>全部副本的进入许可 (实际按每个 <code>emakidungeon.dungeon.&lt;副本ID&gt;</code> 逐个校验)</td></tr><tr><td><code>emakidungeon.bypass.limit</code></td><td>OP</td><td>绕过次数与冷却限制</td></tr><tr><td><code>emakidungeon.bypass.escape</code></td><td>OP</td><td>逃逸防护豁免 (调试与维护用)</td></tr><tr><td><code>emakidungeon.script</code></td><td>OP</td><td>副本脚本装载与触发器注册</td></tr><tr><td><code>emakidungeon.editor</code></td><td>OP</td><td>地图编辑器会话</td></tr><tr><td><code>emakidungeon.admin</code></td><td>OP</td><td>实例管理, 强制结束, 重载, 池维护</td></tr><tr><td><code>emakidungeon.*</code></td><td>OP</td><td>以上全部的通配节点</td></tr></tbody></table><p><code>emakidungeon.dungeon.&lt;副本ID&gt;</code> 在插件启动与重载时按 <code>world/</code> 下的副本目录<strong>动态注册</strong>, 默认所有玩家都能进; 副本被删除时对应节点一并移除. 想做&quot;会员专属副本&quot;, 你在权限插件里把该节点的默认值关掉, 只授予指定组即可</p><h2 id="副本内的命令限制" tabindex="-1">副本内的命令限制 <a class="header-anchor" href="#副本内的命令限制" aria-label="Permalink to “副本内的命令限制”">​</a></h2><p>进入副本后, 玩家发出的命令会依次过两道闸:</p><ol><li><strong>逃逸黑名单</strong> (<code>escape.blacklist</code>, 支持通配符): 命中直接拒绝, 提示&quot;该命令在本副本受限 (逃逸黑名单)&quot;, 这一层<strong>不可被任何放行条目豁免</strong></li><li><strong>命令管控</strong> (<code>commands.mode</code> 为黑名单或白名单模式): 按全局 <code>commands.rules</code> 与副本级 <code>commands.allow</code> 判定, 拒绝时提示&quot;该命令在本副本受限 (命令管控)&quot;</li></ol><p>详情与配置写法见 <a href="./configuration.html">配置详解</a></p>`,34)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};